import{_ as o,o as r,c as n,ag as s}from"./chunks/framework.D5hoimZQ.js";const m=JSON.parse('{"title":"🔬 科学日报 | 2026年10月27日 · 深度扩展","description":"","frontmatter":{"sidebar":true},"headers":[],"relativePath":"science-log/src/science-daily/2026-10-27.md","filePath":"science-log/src/science-daily/2026-10-27.md"}'),e={name:"science-log/src/science-daily/2026-10-27.md"};function a(c,t,g,i,d,p){return r(),n("div",null,[...t[0]||(t[0]=[s('<h1 id="🔬-科学日报-2026年10月27日-·-深度扩展" tabindex="-1">🔬 科学日报 | 2026年10月27日 · 深度扩展 <a class="header-anchor" href="#🔬-科学日报-2026年10月27日-·-深度扩展" aria-label="Permalink to &quot;🔬 科学日报 | 2026年10月27日 · 深度扩展&quot;">​</a></h1><blockquote><p>来源：科学快报 第46期（10 条简讯：科学前沿 5 + AI前沿 5） 分析日期：2026-10-27 版本：扩展版（10 条深度 + 交叉关联）</p></blockquote><hr><h2 id="🔬-一、科学前沿" tabindex="-1">🔬 一、科学前沿 <a class="header-anchor" href="#🔬-一、科学前沿" aria-label="Permalink to &quot;🔬 一、科学前沿&quot;">​</a></h2><h3 id="_1-术后「ctdna-清零」比病理完全缓解更能预测肺癌不复发" tabindex="-1">1. 术后「ctDNA 清零」比病理完全缓解更能预测肺癌不复发 <a class="header-anchor" href="#_1-术后「ctdna-清零」比病理完全缓解更能预测肺癌不复发" aria-label="Permalink to &quot;1. 术后「ctDNA 清零」比病理完全缓解更能预测肺癌不复发&quot;">​</a></h3><p><strong>原文</strong>：可切除非小细胞肺癌（NSCLC）即使接受围手术期治疗，复发风险仍高。NeoCOAST-2（NCT05061550）是一项 2 期随机平台试验，在 IIA–IIIB 期 NSCLC 上检验新辅助/辅助新方案：标准化疗 + 度伐利尤单抗（抗 PD-L1），分别再联合 oleclumab（Arm 1，n=76）、monalizumab（Arm 2，n=72）或 datopotamab deruxtecan（Dato-DXd，Arm 4，n=54）。本文首次报告预设次要终点——无事件生存（EFS）与循环肿瘤 DNA（ctDNA）清除，并探索 ctDNA 动态与临床结局的关联。24 个月 EFS 率分别为 70.5%、75.7%、77.9%；新辅助第 3 周期第 1 天用肿瘤无关检测测得的 ctDNA 清除率以 Arm 4 最高（三臂 50.9%、54.5%、72.5%）。ctDNA 清除与 EFS 延长显著相关（合并 HR 0.22，95% CI 0.11–0.45，P=0.0000443）；ctDNA 清除 + 病理完全缓解（pCR）双达标者结局最优（EFS HR 0.10）。作者认为联合评估 ctDNA 清除与 pCR 可改善风险分层，Dato-DXd 组数值最高的 pCR 与 EFS 值得进一步评估。</p><p><strong>深度扩展</strong>：</p><p>这篇发表于《Nature》（2026，DOI 10.1038/s41586-026-11328-3）的报告，给出的是「如何读懂术后残存病灶」的一个方法论升级，而非某个新药的有效性结论。NeoCOAST-2 本身是一个<strong>平台试验</strong>（platform trial）——同一主方案下并行多个联合臂、共享对照，用统一入组与终点实现快速筛选，因此它的价值在「比较不同联合方案的信号强度」，而不是「证明某一臂优于标准治疗」。</p><p>关键在于<strong>两种读数的维度不同</strong>。pCR（病理完全缓解）读的是<strong>手术标本</strong>：它是单一快照，且受取样误差（只取了部分病灶、淋巴结采样不完整）与治疗后空间异质性影响。ctDNA 清除读的是<strong>全身循环中的肿瘤 DNA</strong>——由所有残存病灶（包括影像与病理都覆盖不到的微转移）共同贡献，是「全身总和的动态读数」。检测采用<strong>肿瘤无关（tumor-agnostic）</strong> assay，即不依赖每个患者预先测序肿瘤突变，而是用固定 panel 捕获常见肿瘤变异，因此可标准化、可规模化落地。</p><p>第三个要点是<strong>动态性</strong>：清除在<strong>新辅助第 3 周期第 1 天</strong>（治疗中途）测量——这是「治疗是否真的打到肿瘤」的早期读出，比等手术后再看病理提前了数周。统计上，清除与 EFS 的合并 HR 为 0.22，清除 + pCR 双达标者 HR 降到 0.10，说明两者<strong>互补而非替代</strong>（分子维度 + 形态维度）。</p><p>为什么重要：如果 ctDNA 清除能作为可靠的<strong>替代终点（surrogate endpoint）</strong>，围手术期试验的读出期可从数年缩短到数月，且可用于<strong>升阶/降阶治疗决策</strong>（清零者减疗、不清零者强化）。克制表述：这是 2 期平台试验的<strong>预设次要终点</strong>，未按臂做效力检验，需 3 期验证，不能据此宣布 Dato-DXd 方案优越。</p><p><strong>跨主题关联</strong>：与 <code>topics/biomedicine/index.md</code> 反复出现的「分子层面的<strong>状态</strong>读数优于形态学的<strong>结构</strong>快照」同源；本条的落盘延伸见 <code>topics/biomedicine/science-daily-2026-10-27-biomed.md</code>。</p><hr><h3 id="_2-内脏脂肪单细胞图谱锁定-thbs1-纤维化—炎症的真正推手" tabindex="-1">2. 内脏脂肪单细胞图谱锁定 THBS1：纤维化—炎症的真正推手 <a class="header-anchor" href="#_2-内脏脂肪单细胞图谱锁定-thbs1-纤维化—炎症的真正推手" aria-label="Permalink to &quot;2. 内脏脂肪单细胞图谱锁定 THBS1：纤维化—炎症的真正推手&quot;">​</a></h3><p><strong>原文</strong>：脂肪组织的细胞复杂性在代谢病发病中起关键作用，但脂肪功能障碍的机制长期不清楚。作者对代谢状态明确的同质人群（血糖正常偏瘦、肥胖、肥胖合并 2 型糖尿病）的人内脏脂肪构建单核与整体转录组图谱。单核 RNA 测序发现一个<strong>高表达 THBS1 的纤维化—炎症型脂肪干细胞/脂肪细胞亚群</strong>，在肥胖与肥胖合并 2 型糖尿病者中富集。通过体外（人原代脂肪干细胞、THP-1 巨噬细胞、Matrigel 捕获的成熟脂肪细胞）、离体（人/小鼠内脏脂肪外植体）与体内（功能获得 + 抗体中和）实验，作者证明 THBS1 经<strong>巨噬细胞介导的 TGFβ 激活</strong>促进脂肪纤维化与炎症，损害脂肪生成与脂肪细胞功能；抑制 THBS1 可缓解代谢失调脂肪组织的纤维化—炎症特征。血浆与脂肪细胞 THBS1 水平与 BMI、HbA1c 等代谢指标相关，提示 THBS1 是潜在治疗靶点。</p><p><strong>深度扩展</strong>：</p><p>这篇发表于《Nature Communications》（2026，DOI 10.1038/s41467-026-77107-w）的工作，把「肥胖导致脂肪组织发炎」这句常识，拆成了「<strong>哪个细胞亚群在驱动</strong>」。作者的实验设计有三层：<strong>单核 RNA 测序</strong>定位驱动者（在单细胞分辨率下发现一个 THBS1 高表达的脂肪干细胞/前体亚群）、<strong>体外/离体系统</strong>验证通路（原代人脂肪干细胞 + THP-1 巨噬细胞共培养、人/鼠内脏脂肪外植体）、<strong>体内功能获得与抗体中和</strong>证明必要性——三段证据链缺一不可，才把「相关」升级为「因果驱动」。</p><p>THBS1（thrombospondin-1，血小板反应蛋白-1）本身不是新分子，但这里给了它一个<strong>新的角色定位</strong>：它属于基质细胞蛋白（matricellular protein），经典功能是结合<strong>潜在型 TGF-β 复合物</strong>（latent TGF-β，通过 LAP 与 LSKL 序列）并诱导构象改变，从而把「休眠的 TGF-β」变成「活性的 TGF-β」。本篇的机制链条是：THBS1 → <strong>巨噬细胞介导的 TGF-β 激活</strong> → 成纤维化 + 炎症 + 抑制脂肪生成。换句话说，脂肪组织里的炎症不是「脂肪细胞普遍在喊痛」，而是<strong>一个特定亚群在指挥巨噬细胞</strong>。</p><p>为什么重要：TGF-β 是纤维化研究的经典靶点，但它全身性广泛、直接抑制副作用大；把上游「激活者」定位到一个<strong>可被抗体中和的分泌蛋白</strong>（THBS1），等于找到了一个更窄的干预窗口。血浆 THBS1 与 BMI、HbA1c 相关，也让它有潜力成为<strong>分型生物标志物</strong>（谁属于「纤维化—炎症型肥胖」）。克制表述：这是机制与临床前证据，尚未有 THBS1 抑制剂的人体代谢病试验数据。</p><p><strong>跨主题关联</strong>：与 <code>topics/biomedicine/index.md</code> 的「<strong>一个细胞亚群 ≠ 一种组织</strong>，功能由子群而非平均决定」同构；本条落盘延伸见 <code>topics/biomedicine/science-daily-2026-10-27-biomed.md</code>。</p><hr>',21)])])}const T=o(e,[["render",a]]);export{m as __pageData,T as default};
